$inactive=$tomorrow->save([...$body,'salary'=>'62000','shifts'=>['Afternoon','Night'],'revision'=>2,'endDate'=>'2026-10-22'],'admin',$id);$later=new OMT\Employees($s,'2026-10-25');check(count($later->detail($id,'2026-10')[1]['data']['attendance'])===7);
