$deposit=[...$entry,'type'=>'repayment','amount'=>'200','requestId'=>'cccccccc-1234-1234-1234-123456789abc'];$cashSvc->cash($wid,$deposit,'admin');denied(fn()=>$cashSvc->cash($wid,[...$deposit,'amount'=>'801','requestId'=>'dddddddd-1234-1234-1234-123456789abc'],'admin'),400);$cp=$cashSvc->detail($wid,'current')[1]['data']['payroll'];check($cp['advanceOutstandingPaise']===80000&&$cp['cashPayablePaise']===3020000);
